import{_ as n,a0 as p,w as d,s as r,ao as o,I as a,a1 as e,A as l,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"fold 命令入門示例教程 | LCTT x X-CMD","titleTemplate":false,"description":"fold 命令入門示例教程 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"fold 命令入門示例教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"fold 命令入門示例教程 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180111 The Fold Command Tutorial With Examples For Beginners","title":"fold 命令入門示例教程","tag":"201803","desc":""},"relativePath":"201803/20180111 The Fold Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),h={name:"201803/20180111 The Fold Command Tutorial With Examples For Beginners.md"};function g(c,t,u,m,f,k){const i=p("Link");return d(),r("div",null,[t[14]||(t[14]=o('<h1 id="fold-命令入門示例教程" tabindex="-1">fold 命令入門示例教程 <a class="header-anchor" href="#fold-命令入門示例教程" aria-label="Permalink to “fold 命令入門示例教程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/01/Fold-Command-2-720x340.png" alt=""></p><p>你有沒有發現自己在某種情況下想要摺疊或中斷命令的輸出，以適應特定的寬度？在運行虛擬機的時候，我遇到了幾次這種的情況，特別是沒有 GUI 的服務器。 以防萬一，如果你想限制一個命令的輸出為一個特定的寬度，現在看看這裏！ <code>fold</code> 命令在這裏就能派的上用場了！ <code>fold</code> 命令會以適合指定的寬度調整輸入文件中的每一行，並將其打印到標準輸出。</p><p>在這個簡短的教程中，我們將看到 <code>fold</code> 命令的用法，帶有實例。</p><h3 id="fold-命令示例教程" tabindex="-1">fold 命令示例教程 <a class="header-anchor" href="#fold-命令示例教程" aria-label="Permalink to “fold 命令示例教程”">​</a></h3><p><code>fold</code> 命令是 GNU coreutils 包的一部分，所以我們不用為安裝的事情煩惱。</p><p><code>fold</code> 命令的典型語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold [OPTION]... [FILE]...</span></span></code></pre></div><p>請允許我向您展示一些示例，以便您更好地瞭解 <code>fold</code> 命令。 我有一個名為 <code>linux.txt</code> 文件，內容是隨機的。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-1.png" alt=""></p><p>要將上述文件中的每一行換行為默認寬度，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold linux.txt</span></span></code></pre></div><p>每行 80 列是默認的寬度。 這裏是上述命令的輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-2.png" alt=""></p><p>正如你在上面的輸出中看到的，<code>fold</code> 命令已經將輸出限制為 80 個字符的寬度。</p><p>當然，我們可以指定您的首選寬度，例如 50，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -w50 linux.txt</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-3-1.png" alt=""></p><p>我們也可以將輸出寫入一個新的文件，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -w50 linux.txt &gt; linux1.txt</span></span></code></pre></div><p>以上命令將把 <code>linux.txt</code> 的行寬度改為 50 個字符，並將輸出寫入到名為 <code>linux1.txt</code> 的新文件中。</p><p>讓我們檢查一下新文件的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat linux1.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-4.png" alt=""></p><p>你有沒有注意到前面的命令的輸出？ 有些詞在行之間被中斷。 為了解決這個問題，我們可以使用 <code>-s</code> 標誌來在空格處換行。</p><p>以下命令將給定文件中的每行調整為寬度 50，並在空格處換到新行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -w50 -s linux.txt</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-5-1.png" alt=""></p><p>看清楚了嗎？ 現在，輸出很清楚。 換到新行中的單詞都是用空格隔開的，所在行單詞的長度大於 50 的時候就會被調整到下一行。</p><p>在所有上面的例子中，我們用列來限制輸出寬度。 但是，我們可以使用 <code>-b</code> 選項將輸出的寬度強制為指定的字節數。 以下命令以 20 個字節中斷輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fold -b20 linux.txt</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/01/fold-command-6-1.png" alt=""></p><p>另請閲讀：</p>',36)),a("ul",null,[a("li",null,[e(i,{href:"https://www.ostechnix.com/uniq-command-tutorial-examples-beginners/"},{default:l(()=>[...t[0]||(t[0]=[s("Uniq 命令入門級示例教程",-1)])]),_:1})])]),t[15]||(t[15]=o('<p>有關更多詳細信息，請參閲 man 手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man fold</span></span></code></pre></div><p>這些就是所有的內容了。 您現在知道如何使用 <code>fold</code> 命令以適應特定的寬度來限制命令的輸出。 我希望這是有用的。 我們將每天發佈更多有用的指南。 敬請關注！</p><p>乾杯!</p><hr>',5)),a("p",null,[t[2]||(t[2]=s("via: ",-1)),e(i,{href:"https://www.ostechnix.com/fold-command-tutorial-examples-beginners/"},{default:l(()=>[...t[1]||(t[1]=[s("https://www.ostechnix.com/fold-command-tutorial-examples-beginners/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=s("作者：",-1)),e(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...t[3]||(t[3]=[s("SK",-1)])]),_:1}),t[7]||(t[7]=s(" 譯者：",-1)),e(i,{href:"https://github.com/Flowsnow"},{default:l(()=>[...t[4]||(t[4]=[s("Flowsnow",-1)])]),_:1}),t[8]||(t[8]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[s("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[9]||(t[9]=[s("LCTT",-1)])]),_:1}),t[12]||(t[12]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:l(()=>[...t[10]||(t[10]=[s("Linux中國",-1)])]),_:1}),t[13]||(t[13]=s(" 榮譽推出",-1))])])}const C=n(h,[["render",g]]);export{w as __pageData,C as default};
